strategy("Example Strategy", overlay=true, pyramiding=0, process_orders_on_close=true)
length = input.int(20, "Length")
basis = ta.ema(close, length)
if (barstate.isconfirmed and ta.crossover(close, basis))
    strategy.entry("Long", strategy.long)
if (barstate.isconfirmed and ta.crossunder(close, basis))
    strategy.close("Long")
